const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/inlineextends";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  fs.writeFileSync(path.join(dir, file), text);
}

// Root config: a setup file, and one inline project with no extends option.
write("vitest.config.mjs", [
  "export default {",
  "  test: {",
  "    setupFiles: ['./setup.mjs'],",
  "    projects: [",
  "      { test: { name: 'unit', include: ['*.test.mjs'] } },",
  "    ],",
  "  },",
  "}",
].join("\n") + "\n");
write("setup.mjs", "globalThis.__ROOT_SETUP__ = 'yes'\n");
write("probe.test.mjs", [
  "import { test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "test('probe', () => {",
  "  writeFileSync(new URL('./seen.txt', import.meta.url), String(globalThis.__ROOT_SETUP__))",
  "})",
].join("\n") + "\n");

const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const seenFile = path.join(dir, "seen.txt");
if (!fs.existsSync(seenFile)) {
  console.error("ERROR: the probe test did not run (exit " + r.status + ")");
  process.exit(2);
}
const seen = fs.readFileSync(seenFile, "utf8");
if (seen === "yes" && r.status === 0) {
  console.log("PASS: the inline project ran the root setupFiles");
  process.exit(0);
}
// The symptom of the old behavior: the inline project ignored the root config.
if (seen === "undefined" && r.status === 0) {
  console.error("FAIL: the inline project without extends did not inherit the root setupFiles");
  process.exit(1);
}
console.error("ERROR: unexpected result (seen " + JSON.stringify(seen) + ", exit " + r.status + ")");
process.exit(2);

